import pytest
from tenacity import Retrying, TryAgain, retry_never, stop_after_attempt

def test_bug():
    class CustomError(Exception):
        pass

    @Retrying(retry=retry_never, stop=stop_after_attempt(1), reraise=True)
    fn_retry():
        try:
            raise CustomError("underlying error")
        except CustomError:
            raise TryAgain()

    with pytest.raises(CustomError):
        fn_retry()

import pytest
from tenacity import Retrying, TryAgain, retry_never, stop_after_attempt

class CustomError(Exception):
    pass

def test_bug():
    @Retrying(retry=retry_never, stop=stop_after_attempt(1), reraise=True)
    def fn():
        try:
            raise CustomError("underlying error")
        except CustomError:
            raise TryAgain()

    with pytest.raises(CustomError) as exc_info:
        fn()
    assert "underlying error" in str(exc_info.value)

